script:
(function () {
  'use strict';
  // Blended (weighted average) mortgage rate across two or more loans.
  //   Blended rate = sum(balance_k x rate_k) / sum(balance_k).
  //   Amortizing loan payment M = B x i / (1 - (1 + i)^-n), i = rate / 12, n = years left x 12 (B / n at 0%).
  //   Interest-only loan: payment B x i each month, with the balance due at the end of its term.
  //   Effective rate: the annual rate (monthly rate x 12) that discounts the combined monthly payments
  //   (plus interest-only balloons) back to the total balance, found by bisection. It differs from the
  //   blended rate when the loans have different terms.
  // Checked in Node (scratchpad tests/w3b3_brm.test.js): $320,000 at 3.25% + $60,000 at 8.5% -> blended
  //   (10,400 + 5,100) / 380,000 = 4.0789%; payments $1,559.41 (25 yrs) + $590.84 (15 yrs), effective rate 3.872% and $194,175
  //   interest left match an independent Python computation; a single loan's effective rate equals its own rate; equal rates give
  //   that rate for both measures; the effective rate lies between the lowest and highest rate; 0% loans
  //   work; blank rows are ignored and invalid input shows an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var MAX_LOANS = 6, MIN_LOANS = 2, rowCounter = 0;
  var DEFAULTS = [
    { balance: 320000, rate: 3.25, years: 25, type: 'amortizing' },
    { balance: 60000, rate: 8.5, years: 15, type: 'amortizing' }
  ];

  function $(id) { return document.getElementById(id); }
  function setText(id, text) { $(id).textContent = text; }
  function parse(raw, blankAsZero) {
    raw = String(raw).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }
  function read(id, blankAsZero) { return parse($(id).value, blankAsZero); }
  function pct(x, d) { return (x * 100).toFixed(d === undefined ? 3 : d).replace(/\.?0+$/, '') + '%'; }

  // ---- Loan rows (DOM methods only) ----
  function make(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text) e.textContent = text;
    return e;
  }

  function numberField(id, label, value, affix, affixFirst, step, max) {
    var wrap = make('div');
    var lab = make('label', 'form-label', label);
    lab.setAttribute('for', id);
    var group = make('div', 'input-group');
    var input = make('input', 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none');
    input.type = 'number'; input.id = id; input.min = '0'; input.step = step; input.inputMode = 'decimal';
    if (max) input.max = max;
    input.value = value === undefined ? '' : String(value);
    var a = make('span', 'input-affix', affix);
    if (affixFirst) { group.appendChild(a); group.appendChild(input); } else { group.appendChild(input); group.appendChild(a); }
    wrap.appendChild(lab); wrap.appendChild(group);
    return wrap;
  }

  function addLoanRow(d) {
    var list = $('brmLoans');
    rowCounter++;
    var n = rowCounter;
    var row = make('div', 'space-y-3 rounded-xl border border-line p-4');
    row.setAttribute('data-loan-row', String(n));
    var head = make('div', 'flex items-center justify-between gap-3');
    var title = make('p', 'text-sm font-semibold text-ink', 'Loan');
    title.setAttribute('data-loan-title', '');
    var remove = make('button', 'button-secondary h-9 px-3 text-sm', 'Remove');
    remove.type = 'button';
    remove.setAttribute('data-remove', '');
    remove.addEventListener('click', function () {
      if (list.querySelectorAll('[data-loan-row]').length <= MIN_LOANS) return;
      row.remove();
      refreshRows();
      update();
    });
    head.appendChild(title); head.appendChild(remove);
    row.appendChild(head);

    var pair = make('div', 'form-row form-row-2');
    pair.appendChild(numberField('brmBal' + n, 'Balance', d.balance, '$', true, '1000'));
    pair.appendChild(numberField('brmRate' + n, 'Interest rate', d.rate, '%', false, '0.125', '30'));
    row.appendChild(pair);

    var pair2 = make('div', 'form-row form-row-2');
    pair2.appendChild(numberField('brmYears' + n, 'Years left', d.years, 'yrs', false, '1', '50'));
    var typeWrap = make('div');
    var typeLab = make('label', 'form-label', 'Payments');
    typeLab.setAttribute('for', 'brmType' + n);
    var sel = make('select', 'form-select');
    sel.id = 'brmType' + n;
    [['amortizing', 'Principal and interest'], ['interest', 'Interest only']].forEach(function (o) {
      var opt = make('option', '', o[1]);
      opt.value = o[0];
      if (o[0] === d.type) opt.selected = true;
      sel.appendChild(opt);
    });
    sel.value = d.type;
    typeWrap.appendChild(typeLab); typeWrap.appendChild(sel);
    pair2.appendChild(typeWrap);
    row.appendChild(pair2);
    list.appendChild(row);
    refreshRows();
  }

  function refreshRows() {
    var rows = $('brmLoans').querySelectorAll('[data-loan-row]');
    rows.forEach(function (row, i) {
      row.querySelector('[data-loan-title]').textContent = 'Loan ' + (i + 1) + (i === 0 ? ' (first mortgage)' : '');
      var btn = row.querySelector('[data-remove]');
      btn.disabled = rows.length <= MIN_LOANS;
      btn.setAttribute('aria-label', 'Remove loan ' + (i + 1));
    });
    $('brmAdd').disabled = rows.length >= MAX_LOANS;
  }

  function readLoans() {
    var rows = $('brmLoans').querySelectorAll('[data-loan-row]'), loans = [], bad = '';
    rows.forEach(function (row, idx) {
      var n = row.getAttribute('data-loan-row');
      var bal = read('brmBal' + n, true), rate = read('brmRate' + n), years = read('brmYears' + n), type = $('brmType' + n).value;
      if (isNaN(bal) || bal < 0) { bad = bad || 'Loan ' + (idx + 1) + ': the balance cannot be negative.'; return; }
      if (bal === 0) return;
      if (isNaN(rate) || rate < 0 || rate > 30) { bad = bad || 'Loan ' + (idx + 1) + ': enter an interest rate from 0% to 30%.'; return; }
      if (isNaN(years) || years < 1 || years > 50 || years % 1 !== 0) { bad = bad || 'Loan ' + (idx + 1) + ': enter 1 to 50 whole years left.'; return; }
      loans.push({ label: 'Loan ' + (idx + 1), balance: bal, rate: rate, years: years, type: type });
    });
    return { loans: loans, error: bad };
  }

  // ---- Maths ----
  function schedule(loan) {
    // Monthly cash flows (index 0 = month 1) plus interest totals.
    var i = loan.rate / 100 / 12, n = loan.years * 12, flows = new Array(n), firstYear = 0, M;
    if (loan.type === 'interest') {
      M = loan.balance * i;
      for (var k = 0; k < n; k++) flows[k] = M;
      flows[n - 1] += loan.balance;
      firstYear = M * Math.min(12, n);
      return { payment: M, flows: flows, interest: M * n, firstYear: firstYear };
    }
    M = i === 0 ? loan.balance / n : loan.balance * i / (1 - Math.pow(1 + i, -n));
    var b = loan.balance;
    for (var m = 0; m < n; m++) {
      flows[m] = M;
      if (m < 12) firstYear += b * i;
      b = b * (1 + i) - M;
    }
    return { payment: M, flows: flows, interest: M * n - loan.balance, firstYear: firstYear };
  }

  function pvAt(flows, r) {
    var pv = 0, d = 1;
    for (var m = 0; m < flows.length; m++) { d /= (1 + r); pv += flows[m] * d; }
    return pv;
  }

  function effectiveRate(flows, total) {
    // PV falls as r rises; total payments >= total balance whenever every rate >= 0.
    var lo = 0, hi = 0.03;
    if (pvAt(flows, lo) <= total) return 0;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (pvAt(flows, mid) > total) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2 * 12;
  }

  function newLoan(P, rate, years) {
    var i = rate / 100 / 12, n = years * 12;
    var M = i === 0 ? P / n : P * i / (1 - Math.pow(1 + i, -n));
    var b = P, fy = 0;
    for (var m = 0; m < 12 && m < n; m++) { fy += b * i; b = b * (1 + i) - M; }
    return { payment: M, interest: M * n - P, firstYear: fy };
  }

  function clearResults() {
    ['brmBlended', 'brmEffective', 'brmBalance', 'brmPayment', 'brmNote'].forEach(function (id) { setText(id, '–'); });
    $('brmTable').innerHTML = '';
    $('brmVs').innerHTML = '';
  }

  function update() {
    var r = readLoans();
    var newRate = read('brmNewRate'), newTerm = parseInt($('brmNewTerm').value, 10), newCosts = read('brmNewCosts', true);
    var error = $('brmError'), msg = r.error;
    if (!msg && r.loans.length === 0) msg = 'Enter the balance of at least one loan.';
    if (!msg && (isNaN(newRate) || newRate < 0 || newRate > 30)) msg = 'Enter a new loan rate from 0% to 30% under More options.';
    if (!msg && (isNaN(newCosts) || newCosts < 0)) msg = 'Closing costs on the new loan cannot be negative.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var loans = r.loans, total = 0, weighted = 0, payment = 0, interest = 0, firstYear = 0, maxN = 0;
    loans.forEach(function (l) {
      l.s = schedule(l);
      total += l.balance; weighted += l.balance * l.rate / 100;
      payment += l.s.payment; interest += l.s.interest; firstYear += l.s.firstYear;
      maxN = Math.max(maxN, l.s.flows.length);
    });
    var flows = [];
    for (var m = 0; m < maxN; m++) flows.push(0);
    loans.forEach(function (l) { l.s.flows.forEach(function (f, k) { flows[k] += f; }); });
    var blended = weighted / total, eff = effectiveRate(flows, total);

    setText('brmBlended', pct(blended));
    setText('brmEffective', pct(eff));
    setText('brmBalance', money0.format(total));
    setText('brmPayment', money.format(payment));

    var note = 'Your loans cost a blended ' + pct(blended) + ' a year, the rate a single loan of ' + money0.format(total) +
      ' would need to charge the same interest in the first month.';
    if (loans.length > 1 && Math.abs(eff - blended) >= 0.00005) {
      note += ' Over the remaining terms the effective rate is ' + pct(eff) + ': ' +
        (eff > blended ? 'your higher-rate balances shrink more slowly than the rest, so they make up a bigger share of what you owe over time.'
                       : 'your higher-rate balances shrink faster than the rest, so they make up a smaller share of what you owe over time.');
    }
    setText('brmNote', note);

    $('brmTable').innerHTML = loans.map(function (l) {
      return '<tr><td>' + l.label + '</td><td>' + money0.format(l.balance) + '</td><td>' + pct(l.balance / total, 1) + '</td><td>' +
        pct(l.rate / 100) + '</td><td>' + pct(l.balance / total * l.rate / 100) + '</td><td>' + money.format(l.s.payment) +
        (l.type === 'interest' ? ' (interest only)' : '') + '</td><td>' + money0.format(l.s.interest) + '</td></tr>';
    }).join('') + '<tr><th scope="row">Total</th><td>' + money0.format(total) + '</td><td>100%</td><td>–</td><td>' + pct(blended) +
      '</td><td>' + money.format(payment) + '</td><td>' + money0.format(interest) + '</td></tr>';

    var nl = newLoan(total, newRate, newTerm);
    setText('brmNewCol', 'New loan (' + pct(newRate / 100) + ', ' + newTerm + ' yrs)');
    var vs = [
      ['Rate', pct(blended) + ' blended', pct(newRate / 100)],
      ['Monthly payment', money.format(payment), money.format(nl.payment)],
      ['Interest in the first year', money0.format(firstYear), money0.format(nl.firstYear)],
      ['Interest left to pay', money0.format(interest), money0.format(nl.interest)],
      ['Interest plus closing costs', money0.format(interest), money0.format(nl.interest + newCosts)]
    ];
    $('brmVs').innerHTML = vs.map(function (v) {
      return '<tr><th scope="row">' + v[0] + '</th><td>' + v[1] + '</td><td>' + v[2] + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = $('brmForm');
    if (!form) return;
    DEFAULTS.forEach(addLoanRow);
    $('brmAdd').addEventListener('click', function () {
      if ($('brmLoans').querySelectorAll('[data-loan-row]').length >= MAX_LOANS) return;
      addLoanRow({ balance: '', rate: '', years: '', type: 'amortizing' });
      update();
    });
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
